import {HOUR,growthProgress} from './growth.js?v=simulation15';
export const FIELD={x:-8.4,z:15.3,width:10.1,depth:10.2,minX:-13.45,maxX:-3.35,minZ:10.2,maxZ:20.4,approach:{x:-3,z:15}};
export const WALK_SPEED=4.5;
export const CROPS=Object.freeze({maize:{name:'Maize',seed:'seeds',good:'maize',seeds:4,water:6,yield:24,hours:24,height:1.8},wheat:{name:'Wheat',seed:'wheatSeeds',good:'wheat',seeds:4,water:4,yield:20,hours:18,height:1},sunflower:{name:'Sunflower',seed:'sunflowerSeeds',good:'sunflower',seeds:3,water:5,yield:14,hours:36,height:2.1},vegetables:{name:'Vegetables',seed:'vegetableSeeds',good:'vegetables',seeds:4,water:6,yield:18,hours:12,height:.5}});
export function ensureCrops(s){s.inventory??={};if(!Number.isFinite(s.inventory.seeds))s.inventory.seeds=8;if(!('crop'in s))s.crop=null;if(!s.cropBeds)s.cropBeds=[s.crop,null,null,null];s.crop=s.cropBeds[0];for(const [id,c]of Object.entries(CROPS)){if(s.inventory[c.seed]===undefined)s.inventory[c.seed]=0;if(s.inventory[c.good]===undefined)s.inventory[c.good]=0;if(Array.isArray(s.offers)&&!s.offers.some(o=>o.good===c.seed))s.offers.push({good:c.seed,seller:'Sunfield Seed House',price:3,stock:160,buy:60});if(Array.isArray(s.offers)&&!s.offers.some(o=>o.good===c.good))s.offers.push({good:c.good,seller:'Village buyers',price:typePrice(id),stock:0,buy:120});}return s;}
function typePrice(id){return id==='sunflower'?4:id==='vegetables'?3:2;}
function bed(s,id=0){if(!Number.isInteger(id)||id<0||id>3)throw Error('Choose one of your four crop beds.');return s.cropBeds?s.cropBeds[id]:id===0?s.crop:null;}
export function cropProgress(s,id=0,now=Date.now()){const b=bed(s,id);if(!b||b.wateredDay===null)return 0;const c=CROPS[b.type||'maize'];return growthProgress({startedDay:b.wateredDay,readyDay:b.wateredDay+Math.ceil(c.hours/24),startedAt:b.wateredAt,durationMs:(b.hours||c.hours)*HOUR},s.day,now);}
export function cropStage(s,id=0,now=Date.now()){const b=bed(s,id);if(!b)return 'empty';if(b.wateredDay===null)return 'planted';return cropProgress(s,id,now)>=1?'ready':'growing';}
export function plantSeeds(s,id=0,type='maize',now=Date.now()){if(bed(s,id))throw Error('Harvest this bed before planting it again.');const c=CROPS[type];if(!c)throw Error('Choose a crop variety.');if((s.inventory[c.seed]||0)<c.seeds)throw Error('Planting needs '+c.seeds+' '+c.name+' seeds. Buy seeds at the market.');ensureCrops(s);s.inventory[c.seed]-=c.seeds;s.cropBeds[id]={type,plantedDay:s.day,plantedAt:now,wateredDay:null,hours:c.hours};s.crop=s.cropBeds[0];return c.seeds;}
export function waterCrop(s,id=0,now=Date.now()){const b=bed(s,id);if(!b)throw Error('Plant seeds before watering this bed.');if(b.wateredDay!==null)throw Error('This crop has already been watered.');const c=CROPS[b.type||'maize'];if(s.inventory.water<c.water)throw Error('This bed needs '+c.water+' water.');s.inventory.water-=c.water;b.wateredDay=s.day;b.wateredAt=now;return c.water;}
export function fertiliseCrop(s,id=0,now=Date.now()){const b=bed(s,id);if(!b||b.fertilised||cropStage(s,id,now)==='ready')throw Error('Choose a growing, unfertilised crop bed.');if(s.inventory.fertiliser<2)throw Error('Use 2 fertiliser from animal care.');s.inventory.fertiliser-=2;b.fertilised=true;b.hours=(b.hours||CROPS[b.type||'maize'].hours)*.8;return 2;}
export function harvestCrop(s,id=0,now=Date.now()){if(cropStage(s,id,now)!=='ready')throw Error(bed(s,id)?'Water the crop and let it grow before harvesting.':'Plant seeds first. There is no crop to harvest.');const b=bed(s,id),c=CROPS[b.type||'maize'];s.inventory[c.good]=(s.inventory[c.good]||0)+c.yield;if(s.cropBeds)s.cropBeds[id]=null;s.crop=s.cropBeds?s.cropBeds[0]:null;s.cropReady=0;return c.yield;}
